/**
 * Unit tests for the UserAccessTemporalCodeRecoveryCodeExpirationAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserAccessTemporalCodeRecoveryCodeExpirationAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getRecoveryCodeExpiration returns null on a freshly created holder.
         */
        public function testRecoveryCodeExpirationNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeExpirationAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isRecoveryCodeExpirationAssigned());
            $this->assertNull($holder->getRecoveryCodeExpiration());
        }
}
